use "./board.css"
use Column from "./column.qubc"

component Board {
  props {
    title: string,
    owner: string,
    columns: Omit<Column, 'position'>[]
  }
  contexts {
    BoardArea { board: title, owner: owner }
  }
  events {
    CLICK_ADD({ title })
  }
  template {
    section(class="board") {
      header(class="board__bar") {
        div(class="board__id") {
          h1(class="board__title") { {title} }
          span(class="board__owner") { {owner} }
        }
        button(class="board__add" @click:CLICK_ADD) { "+ 컬럼" }
      }

      @with BoardArea {
        div(class="board__columns") {
          @for (column, index of columns) {
            Lane: Column(
              name={column.name}
              accent={column.accent}
              position={index}
              cards={column.cards}
            /)
          }
        }
      }
    }
  }
}

// 핸들러 키는 풀네임 - use-site에서 바깥부터 안쪽으로 별칭을 누적한다.
// Board가 Column을 Lane으로, Column이 Card를 Ticket으로, Card가 Badge를 Flag/Points로 쓴다.
// 같은 Badge 컴포넌트지만 별칭이 달라 핸들러가 갈린다 - 컴포넌트는 자기 쓰임을 모른다.
// @for 안이라 회차 번호가 [$0](컬럼) / [$1](카드)로 붙는다.

export default {
  CLICK_ADD: (data) => {
    console.log("컬럼 추가:", data.title);
  },

  "Lane[$0].CLICK_ADD": (data, { $0 }) => {
    console.log(`카드 추가: ${data.lane} (${$0}번 컬럼)`);
  },

  "Lane[$0].CLICK_HEADING": (data, { context }) => {
    console.log("컬럼 제목:", data.lane, "/ 보드:", context.BoardArea.board);
  },

  "Lane[$0].Ticket[$1].CLICK_TITLE": (data, { $0, $1, context }) => {
    console.log(`카드: ${data.title}`);
    console.log(`  자리: ${$0}번 컬럼 ${$1}번째`);
    console.log(`  레인: ${context.LaneArea.lane}`);
  },

  "Lane[$0].Ticket[$1].CLICK_OWNER": (data) => {
    console.log("담당자:", data.assignee, "/ 카드:", data.title);
  },

  "Lane[$0].Ticket[$1].Flag.CLICK_BADGE": (data) => {
    console.log("긴급 배지:", data.text);
  },

  "Lane[$0].Ticket[$1].Points.CLICK_BADGE": (data) => {
    console.log("포인트 배지:", data.text);
  },
};

