use "./column.css"
use Card from "./card.qubc"

component Column {
  props {
    name: string,
    accent: string,
    position: number,
    cards: Omit<Card, 'seat'>[]
  }
  contexts {
    LaneArea { lane: name, position: position }
  }
  events {
    CLICK_ADD({ lane: name })
    CLICK_HEADING({ lane: name, position })
  }
  template {
    div(class="col") {
      header(class="col__head" style={accent}) {
        h2(class="col__name" @click:CLICK_HEADING) { {name} }
      }

      @with LaneArea {
        div(class="col__cards") {
          @for (card, seat of cards) {
            Ticket: Card(
              title={card.title}
              assignee={card.assignee}
              points={card.points}
              urgent={card.urgent}
              seat={seat}
            /)
          }
        }
      }

      button(class="col__add" @click:CLICK_ADD) { "+ 카드" }
    }
  }
}

export default {
  CLICK_ADD: (data) => {
    console.log("카드 추가:", data.lane);
  },

  CLICK_HEADING: (data) => {
    console.log("컬럼 제목:", data.lane, "/ 자리:", data.position);
  },

  "Ticket[$0].CLICK_TITLE": (data, { $0, context }) => {
    console.log(`카드: ${data.title} (${$0}번째)`);
    console.log("  레인:", context.LaneArea.lane);
  },

  "Ticket[$0].CLICK_OWNER": (data) => {
    console.log("담당자:", data.assignee);
  },

  "Ticket[$0].Flag.CLICK_BADGE": (data) => {
    console.log("긴급 배지:", data.text);
  },

  "Ticket[$0].Points.CLICK_BADGE": (data) => {
    console.log("포인트 배지:", data.text);
  },
};

