use "./card.css"
use Badge from "./badge.qubc"

component Card {
  props {
    title: string,
    assignee: string,
    points: string,
    urgent: bool,
    seat: number
  }
  events {
    CLICK_TITLE({ title, seat })
    CLICK_OWNER({ title, assignee })
  }
  template {
    article(class="ticket") {
      @if (urgent) {
        Flag: Badge(text="긴급" tone="hot" /)
      }

      h3(class="ticket__title" @click:CLICK_TITLE) { {title} }

      footer(class="ticket__foot") {
        button(class="ticket__who" @click:CLICK_OWNER) { {assignee} }
        Points: Badge(text={points} tone="calm" /)
      }
    }
  }
}

export default {
  CLICK_TITLE: (data) => {
    console.log("카드:", data.title, "/ 자리:", data.seat);
  },

  CLICK_OWNER: (data) => {
    console.log("담당자:", data.assignee);
  },

  "Flag.CLICK_BADGE": (data) => {
    console.log("긴급 배지:", data.text, data.tone);
  },

  "Points.CLICK_BADGE": (data) => {
    console.log("포인트 배지:", data.text, data.tone);
  },
};

.ticket {
  padding: 10px 12px;
  border-radius: 6px;
  background: #fff;
  box-shadow: 0 1px 2px rgba(9, 30, 66, 0.25);
  cursor: pointer;
}

.ticket:hover {
  background: #f7f8f9;
}

.ticket__title {
  margin: 4px 0 10px;
  font-size: 14px;
  line-height: 1.4;
}

.ticket__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.ticket__who {
  padding: 3px 8px;
  border: 0;
  border-radius: 10px;
  background: #dfe1e6;
  color: #42526e;
  font-size: 12px;
  cursor: pointer;
}

.ticket__who:hover {
  background: #c1c7d0;
}

use "./badge.css"

component Badge {
  props { text: string, tone: string }
  events { CLICK_BADGE({ text, tone }) }
  template {
    span(class="badge" data-tone={tone} @click:CLICK_BADGE) { {text} }
  }
}

export default {
  CLICK_BADGE: (data) => {
    console.log("배지:", data.text, "/ 톤:", data.tone);
  },
};

.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.badge[data-tone="hot"] {
  background: #ffebe6;
  color: #bf2600;
}

.badge[data-tone="calm"] {
  background: #deebff;
  color: #0747a6;
}
